function initSliding(){grid(3);let tiles=[1,2,3,4,5,6,7,8,0],zero=8,prev=-1;for(let k=0;k<120;k++){const opts=[zero-3,zero+3,zero%3?zero-1:-1,zero%3<2?zero+1:-1].filter(i=>i>=0&&i<9&&i!==prev),next=opts[rand(opts.length)];[tiles[zero],tiles[next]]=[tiles[next],tiles[zero]];prev=zero;zero=next}if(tiles.every((n,i)=>n===(i+1)%9)){[tiles[7],tiles[8]]=[tiles[8],tiles[7]]}state={tiles,moves:0};renderSliding()}
